import{z as o,x as p,o as E,c as B,q as A,j as n,D as e,d as t,s as l,S as i,b as s}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"PUF","description":"","frontmatter":{"title":"PUF","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/puf.md","filePath":"cs/puf.md","lastUpdated":1791413859000}'),d={name:"cs/puf.md"};function c(h,a,m,D,u,f){const r=p("Mermaid");return E(),B("div",null,[a[2]||(a[2]=A('<h1 id="puf" tabindex="-1">PUF <a class="header-anchor" href="#puf" aria-label="Permalink to &quot;PUF&quot;">​</a></h1><div class="epigraph"><p>物理不可克隆函数把制造差异变成挑战–响应：像指纹，难复制。它可作设备身份与密钥派生，但可靠性、老化与建模攻击要进合同。</p><footer>—— Gassend, Clarke, van Dijk and Devadas, Silicon Physical Random Functions, CCS 2002</footer></div><p>上一课<a href="/cs/fault-injection">故障注入</a>用物理手段扰动计算；本课反过来看：<strong>把制造时的物理差异本身当作身份</strong>，替代把密钥存进存储器。本课讲 PUF 直觉，不写建模攻击的步骤。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>密钥存进非易失存储就有被读出的一天——拆封、探针、冷启动都能碰它。PUF 不存：施加挑战，硅片的制造差异（走线延迟、SRAM 上电偏好）决定响应，同一芯片给出稳定输出而其他芯片无法复制；再经模糊提取把含噪响应收成稳定密钥。缺口有三类：响应误码随温度电压漂移、芯片老化改变响应、公开挑战–响应对喂给机器学习后被建模仿冒。</p><h3 id="不是完善保密" tabindex="-1">不是完善保密 <a class="header-anchor" href="#不是完善保密" aria-label="Permalink to &quot;不是完善保密&quot;">​</a></h3><p>PUF 是硬件身份的候选方案，不是完善保密：没有模糊提取与限次公开挑战，响应表迟早被学穿。</p><p><span class="marginnote">Gassend et al. 2002。禁止克隆实验。Spectre 缓解下一课回微结构。</span></p><p><span class="marginnote">SRAM 上电指纹的直觉：每个存储单元上电时「倒向 0 还是 1」由制造时的微小差异随机定型，像出厂就长好的指纹。同一片芯片次次上电指纹基本一致，换一片就对不上——于是「身份」不需要存任何地方，上电瞬间自己重印一遍。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>方法是把挑战–响应图画清楚，再对照 HSM 存钥：HSM 把密钥封进抗拆外壳，代价是管一个「读不出」的黑盒库存；PUF 的密钥按需从物理派生，不上电就不存在，代价是管误码率与老化。下一课 Spectre 缓解与代价。</p>',12)),(E(),n(i,null,{default:e(()=>[l(r,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20CH%5B%22%E6%8C%91%E6%88%98%22%5D%20--%3E%20PHY%5B%22%E5%88%B6%E9%80%A0%E5%B7%AE%E5%BC%82%22%5D%0A%20%20PHY%20--%3E%20RSP%5B%22%E5%93%8D%E5%BA%94%22%5D%0A%20%20RSP%20--%3E%20FE%5B%22%E6%A8%A1%E7%B3%8A%E6%8F%90%E5%8F%96%E5%BE%97%E9%92%A5%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s("h2",{id:"机制",tabindex:"-1"},[t("机制 "),s("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=s("p",null,"机制的核心是「身份可以不上电存在」：制造差异在断电时也在，密钥只在需要的一刻被提取，攻击面从「读出存储」变成「预测物理」。模糊提取由纠错与哈希两截组成——辅助数据帮纠偏但不泄露密钥本身；老化则要在生命周期里重登记。微结构泄漏下一课是另一条物理/共享硬件轴。",-1)),(E(),n(i,null,{default:e(()=>[l(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20PWR%5B%22%E4%B8%8A%E7%94%B5%20%E8%AF%BB%E5%87%BA%E5%90%AB%E5%99%AA%E5%93%8D%E5%BA%94%22%5D%20--%3E%20AU%5B%22%E5%8F%96%E5%87%BA%E6%B3%A8%E5%86%8C%E6%97%B6%E5%AD%98%E5%A5%BD%E7%9A%84%E8%BE%85%E5%8A%A9%E6%95%B0%E6%8D%AE%22%5D%0A%20%20AU%20--%3E%20EC%5B%22%E7%BA%A0%E9%94%99%E7%A0%81%E6%8A%B9%E5%B9%B3%E6%B8%A9%E5%BA%A6%E7%94%B5%E5%8E%8B%E5%B8%A6%E6%9D%A5%E7%9A%84%E8%AF%AF%E7%A0%81%22%5D%0A%20%20EC%20--%3E%20H%5B%22%E5%93%88%E5%B8%8C%E5%8E%8B%E6%88%90%E7%A8%B3%E5%AE%9A%E5%AF%86%E9%92%A5%22%5D%0A%20%20H%20--%3E%20USE%5B%22%E5%BD%93%E5%9C%BA%E4%BA%A4%E7%BB%99%20KDF%20%E6%88%96%E5%8A%A0%E5%AF%86%E7%94%A8%E5%AE%8C%E5%8D%B3%E5%BC%83%22%5D%0A%20%20REG%5B%22%E6%B3%A8%E5%86%8C%E9%98%B6%E6%AE%B5%20%E5%8F%AA%E5%AD%98%E8%BE%85%E5%8A%A9%E6%95%B0%E6%8D%AE%20%E4%B8%8D%E5%AD%98%E5%93%8D%E5%BA%94%E6%9C%AC%E8%BA%AB%22%5D%20-.%E4%BE%9B%E7%BA%A0%E9%94%99%E7%94%A8.-%3E%20AU%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[5]||(a[5]=A('<p><span class="marginnote">上图回答「模糊提取怎么把噪声响应收成同一个密钥」：注册时只留辅助数据，像给指纹留一张「哪里容易认错」的说明；此后每次上电先纠错、再哈希。响应本身从头到尾没有被存储，读存储的攻击面落了空。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不写建模攻击的步骤；边界要点名：PUF 的可靠性用片内误码率衡量，典型为个位数百分比，正是这个量级的噪声决定了必须配模糊提取。Spectre 缓解下一课。</p><p><span class="marginnote">给个数的感觉：误码率 5% 时，一段 128 位的响应每次上电约有 6 个位翻转。人眼看它仍是「同一枚指纹」，但密钥差一位都全错——纠错码就得按「6 位错」来配容量，这正是辅助数据存在的理由。</span></p><p><span class="marginnote">初学者容易把「物理不可克隆」听成「攻不破」。若公开足够多挑战–响应对，机器学习能拟合出一个软件替身来冒充芯片——所以真正的合同是：挑战限次公开、响应表不出设备，再谈不可克隆。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>故障扰计算；PUF 用差异当指纹。</li><li>模糊提取把噪声响应收成密钥。</li><li>老化与建模要进威胁模型。</li><li>下一课 Spectre 缓解。</li><li>出处：Gassend, Clarke, van Dijk and Devadas, 2002。</li></ul>',7))])}const C=o(d,[["render",c]]);export{_ as __pageData,C as default};
